/** EmbeddingsStore — substrate-tier persistence interface for vector embeddings. */

import type { Candidate, CandidateSelector } from './candidate-selection.js';

export interface EmbeddingsStoreUpsertInput {
  rowNamespace: string;
  rowType: string;
  rowId: string;
  vector: Float32Array;
  /**
   * Embedder identifier (e.g. `some-model:768`). Stored alongside the
   * vector so multi-model coexistence is possible — a `knnSearch` call
   * filters on this so vectors generated by different embedders don't mix.
   */
  model: string;
  /**
   * When the source row was written; defaults to now. An upsert older than
   * the stored vector is ignored, so a slow embed cannot overwrite a newer one.
   */
  now?: Date;
}

/** Identifies the single embedding a `delete` call removes. */
export interface EmbeddingsStoreDeleteInput {
  rowNamespace: string;
  rowType: string;
  rowId: string;
}

export interface EmbeddingsStoreKnnInput {
  /** Row scope. Most callers know exactly one (namespace, type) at recall time. */
  namespace: string;
  type: string;
  /**
   * Active embedder model. Vectors stored under a different model are
   * filtered out — they live in a different vector space and would produce
   * meaningless similarity scores.
   */
  model: string;
  /** The query vector. Must match the model's dimensionality. */
  vector: Float32Array;
  /** Max rows to return. Stores cap at their own ceiling (typically 100). */
  k: number;
  /**
   * Cosine-similarity threshold (0..1). Rows with score below this are
   * dropped. Default 0 (no threshold).
   */
  threshold?: number;
  /**
   * When `true`, each result carries its stored embedding vector. Opt-in
   * because vectors are large and most callers only need scores.
   */
  returnVector?: boolean;
  /**
   * Restrict candidates to rows whose fields match, applied INSIDE the
   * search rather than after it, so a scope like one project in a
   * store shared by several still fills k. Equality family only.
   */
  rowFilter?: KnnRowFilter;
  /**
   * Return each row's salience decayed to now by this half-life, the decay
   * `boostSalience` applies. Absent: the stored value, as of its last boost.
   */
  salienceHalfLifeHours?: number;
}

export type KnnScalar = string | number | boolean | null;
/** Field -> `{ eq }` or `{ in }`; every field must match. `eq: null` matches a missing or null field. */
export type KnnRowFilter = Readonly<
  Record<string, { readonly eq?: KnnScalar; readonly in?: readonly KnnScalar[] }>
>;

/** Field names a row filter may name: plain identifiers, so they are safe to address in SQL. */
export const ROW_FILTER_FIELD = /^[A-Za-z_][A-Za-z0-9_]*$/;

/** Why `value` is not a usable row filter, or null when it is. */
export function rowFilterProblem(value: unknown): string | null {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return 'must be an object of field -> { eq } | { in }';
  }
  const scalar = (x: unknown) => x === null || ['string', 'number', 'boolean'].includes(typeof x);
  for (const [field, pred] of Object.entries(value)) {
    if (!ROW_FILTER_FIELD.test(field)) return `field '${field}' is not a plain identifier`;
    if (pred === null || typeof pred !== 'object') return `'${field}' needs { eq } or { in }`;
    const keys = Object.keys(pred);
    if (keys.length !== 1 || !['eq', 'in'].includes(keys[0] as string)) {
      return `'${field}' takes exactly one of eq / in`;
    }
    const v = (pred as Record<string, unknown>)[keys[0] as string];
    if (keys[0] === 'eq' && !scalar(v)) return `'${field}'.eq must be a scalar or null`;
    if (keys[0] === 'in' && (!Array.isArray(v) || v.length === 0 || !v.every(scalar))) {
      return `'${field}'.in must be a non-empty array of scalars`;
    }
  }
  return null;
}

/** Does a row body satisfy the filter? The in-memory store's semantics, mirrored by pg's SQL. */
export function matchesRowFilter(row: Record<string, unknown>, filter: KnnRowFilter): boolean {
  const same = (a: unknown, b: KnnScalar) =>
    b === null
      ? a === null || a === undefined
      : a !== null && a !== undefined && String(a) === String(b);
  // Own fields only: a field named like an Object.prototype member is absent.
  const value = (field: string): unknown => (Object.hasOwn(row, field) ? row[field] : undefined);
  return Object.entries(filter).every(([field, pred]) =>
    pred.in !== undefined
      ? pred.in.some((v) => same(value(field), v))
      : same(value(field), pred.eq ?? null)
  );
}

export interface EmbeddingsStoreKnnResult {
  /** The full `rows.body` JSON for the matched row. */
  row: Record<string, unknown>;
  /** Cosine similarity in `[0, 1]` — higher is closer. */
  score: number;
  /**
   * Per-row salience: a float counter incremented on each recall hit, with
   * exponential decay applied at boost time. `0` for never-recalled rows.
   */
  salience: number;
  /**
   * The row's stored embedding vector. Present iff the search was called
   * with `returnVector: true`; absent otherwise.
   */
  vector?: number[];
}

/** Identifies one row to bump in a `boostSalience` call. */
export interface SalienceTarget {
  namespace: string;
  type: string;
  id: string;
}

/** One row returned by `fetchEmbeddings` — body joined to the stored vector. */
export interface EmbeddingsStoreFetchResult {
  namespace: string;
  type: string;
  id: string;
  row: Record<string, unknown>;
  vector: Float32Array;
  /** Per-row salience, the same signal `knnSearch` returns. `0` for never-reinforced rows. */
  salience: number;
}

export interface EmbeddingsStore {
  /**
   * Stable identifier for the storage substrate this store wraps; parallels
   * `Dataset.txScopeId` (§5.3). Embedding writes are not enlisted in
   * the substrate tx — they are a fire-and-forget post-write side effect.
   */
  readonly txScopeId: string;

  /**
   * Insert or replace the embedding for a row. Idempotent — repeat calls
   * with the same key tuple overwrite the prior vector + bump `updated_at`.
   *
   * Vector dimensionality is enforced by the substrate (pgvector column
   * type). The store does NOT validate dimensionality client-side; a
   * mismatched vector surfaces as a substrate-level error.
   */
  upsert(input: EmbeddingsStoreUpsertInput): Promise<void>;
  /**
   * Ids of live rows of (namespace, type) whose vector is missing or older than
   * the row, after `afterId` in id order: the writes whose embed failed. Optional;
   * a store that cannot see the rows table omits it and nothing is backfilled.
   */
  staleRowIds?(input: {
    namespace: string;
    type: string;
    afterId: string;
    limit: number;
  }): Promise<string[]>;

  /**
   * Remove the embedding for one row, leaving the row itself untouched. Used
   * to un-index a row whose `embed.source` returns the null sentinel.
   * Idempotent: deleting an absent embedding is a no-op.
   */
  delete(input: EmbeddingsStoreDeleteInput): Promise<void>;

  /**
   * KNN search — return up to `k` rows whose embeddings are closest to
   * `input.vector` (cosine similarity), filtered to the active model.
   * Results are joined against the row body so callers don't need a
   * second round-trip to read the matched rows.
   */
  knnSearch(input: EmbeddingsStoreKnnInput): Promise<EmbeddingsStoreKnnResult[]>;

  /**
   * Apply a salience boost to each target row, with lazy decay:
   *   `salience_new = salience_old * 2^(-elapsed_hours / halfLifeHours) + bump`
   * and `salience_updated_at = now()`. No periodic decay sweep is needed.
   *
   * `bump` defaults to `1` (direct recall hits); activation spreading passes
   * `spreadDamping`. Targets without an embedding row are silent no-ops.
   *
   * Returns the targets that actually matched a stored embedding, in no
   * specified order; callers wanting the misses should difference against
   * what they sent rather than zipping by index.
   */
  boostSalience(
    targets: ReadonlyArray<SalienceTarget>,
    halfLifeHours: number,
    bump?: number
  ): Promise<ReadonlyArray<SalienceTarget>>;

  /**
   * Fetch stored embeddings for a list of row IDs, each joined to its row
   * body. IDs without an embedding under `model` are silently absent. One
   * batched lookup; callers should not loop calling this per ID.
   */
  fetchEmbeddings(
    ids: ReadonlyArray<{ namespace: string; type: string; id: string }>,
    model: string
  ): Promise<ReadonlyArray<EmbeddingsStoreFetchResult>>;

  /**
   * Select clustering candidates — every embedded row under the selector's
   * scopes, minus its exclusions, with vector and body.
   *
   * Ordering is `(namespace, type, id)` ascending and is part of the
   * contract: the clusterer's input feeds a seeded pipeline, so an unstable
   * order would break deterministic assignments.
   *
   * The selector is REQUIRED and has no default. See `validateSelector`.
   */
  selectCandidates(selector: CandidateSelector, model: string): Promise<Candidate[]>;
}
